@model CartModel
<script asp-location="Footer">
    var id = @Model.Id;
    var url = '@Url.Action("Add", "Cart")';
    var data = @Html.Raw(Json.Serialize(Model.Items));
    @* displayNotice("a comment"); *@
    @if (Model.ShowNotice)
    {
        <text>
        displayNotice("@T("Added").Text");
        </text>
    }
    else
    {
        var hidden = Model.Compute();
    }
    $(function () { AjaxCart.add(url); });
</script>

